pipeline {
  agent any
  stages {
    stage('Build') {
      steps {
        sh 'docker login registry.example.com -u $REGISTRY_USER -p $REGISTRY_TOKEN'
      }
    }
  }
}

tasks.withType(Test) {
  maxHeapSize = '512m'
}
